#!/usr/bin/env bash
# ══════════════════════════════════════════════════════════════════════════
#  Escenario Killercoda — Misión CSI (MitM) · Módulo 4 · Clase 6 · CIBER13 UM
#  Autor: Giovanni Cruz.  Genera la carpeta lab-csi-mitm/ en tu repo clonado.
#  Uso:
#     cd um-ciber13-modulo4
#     bash crear-lab-csi.sh
#     git add -A && git commit -m "Clase 6: Mision CSI MitM" && git push
#  Verifica su propia huella SHA-256 antes de extraer.
# ══════════════════════════════════════════════════════════════════════════
set -e
DEST="lab-csi-mitm"
SHA_ESPERADO="222685ebbda75afe1e1bf4eaa420fddb8b31e51425cc677e519285116b95c32e"
TMP=$(mktemp)
cat > "$TMP.b64" <<'B64EOF'

B64EOF
base64 -d < "$TMP.b64" > "$TMP.tgz"
if command -v sha256sum >/dev/null 2>&1; then SHA_REAL=$(sha256sum "$TMP.tgz" | cut -d' ' -f1); else SHA_REAL=$(shasum -a 256 "$TMP.tgz" | cut -d' ' -f1); fi
if [ "$SHA_REAL" != "$SHA_ESPERADO" ]; then
  echo "ERROR: la huella no coincide. El archivo llegó corrupto."; rm -f "$TMP".*; exit 1
fi
mkdir -p "$DEST"
tar xzf "$TMP.tgz" -C "$DEST"
chmod +x "$DEST"/background.sh "$DEST"/verify*.sh "$DEST"/ct-* 2>/dev/null || true
# registrar permisos de ejecución en git (lo que falló antes)
git update-index --add --chmod=+x "$DEST"/background.sh 2>/dev/null || true
for f in "$DEST"/verify1.sh "$DEST"/verify2.sh "$DEST"/ct-abrir "$DEST"/ct-mapa "$DEST"/ct-pista "$DEST"/ct-bandera "$DEST"/ct-retomar "$DEST"/ct-rescate; do
  git update-index --add --chmod=+x "$f" 2>/dev/null || true
done
rm -f "$TMP".*
echo "Escenario creado en $DEST/"
echo "Ahora:  git add -A && git commit -m 'Clase 6: Mision CSI MitM' && git push"
echo "Se publicará en:  https://killercoda.com/cruzgio/scenario/lab-csi-mitm"
